const ZadOffline=(()=>{"use strict";const ONLINE_ONLY={"ai.html":"المساعد الذكي يحتاج اتصالاً بالإنترنت","Quran-radio.HTML":"الإذاعة تحتاج اتصالاً بالإنترنت","playlist.html":"البلاي ليست تحتاج اتصالاً بالإنترنت"};let isOnline=navigator.onLine;function showBanner(online){let banner=document.getElementById("zad-offline-banner");if(!banner){banner=document.createElement("div");banner.id="zad-offline-banner";banner.setAttribute("role","status");document.body.appendChild(banner)}if(online){banner.className="zad-offline-banner online";banner.innerHTML="<span>✅</span><span>عاد الاتصال بالإنترنت</span>";setTimeout(()=>banner.classList.remove("show"),2500)}else{banner.className="zad-offline-banner offline show";banner.innerHTML="<span>📡</span><span>لا يوجد اتصال — المحتوى المحفوظ متاح</span>"}requestAnimationFrame(()=>banner.classList.add("show"))}function blockOnlineFeatures(offline){Object.keys(ONLINE_ONLY).forEach(href=>{document.querySelectorAll(`a[href="${href}"]`).forEach(link=>{if(offline){link.classList.add("zad-disabled-offline");link.dataset.offlineMsg=ONLINE_ONLY[href];link.addEventListener("click",preventOfflineNav)}else{link.classList.remove("zad-disabled-offline");link.removeEventListener("click",preventOfflineNav)}})});const page=window.location.pathname.split("/").pop();if(offline&&ONLINE_ONLY[page]){showFeatureBlock(ONLINE_ONLY[page])}}function preventOfflineNav(e){e.preventDefault();const msg=e.currentTarget.dataset.offlineMsg||"هذه الميزة تحتاج إنترنت";if(window.ZadFeedback)ZadFeedback.toast(msg,"warn");else if(window.showToast)showToast("📡 "+msg)}function showFeatureBlock(msg){if(document.getElementById("zad-feature-block"))return;const block=document.createElement("div");block.id="zad-feature-block";block.className="zad-feature-block";block.innerHTML=`\n      <div class="zfb-icon">📡</div>\n      <div class="zfb-title">لا يوجد اتصال بالإنترنت</div>\n      <div class="zfb-msg">${msg}</div>\n      <button class="zfb-btn" onclick="location.href='index.html'">العودة للرئيسية</button>\n    `;document.body.appendChild(block)}function injectCSS(){if(document.getElementById("zad-offline-css"))return;const s=document.createElement("style");s.id="zad-offline-css";s.textContent=`\n      .zad-offline-banner {\n        position: fixed; top: 0; left: 0; right: 0; z-index: 9990;\n        display: flex; align-items: center; justify-content: center; gap: 8px;\n        padding: 10px 16px; font-size: 13px; font-weight: 700; color: #fff;\n        transform: translateY(-100%); transition: transform .3s var(--ease-out,ease);\n        padding-top: calc(10px + env(safe-area-inset-top, 0px));\n      }\n      .zad-offline-banner.show { transform: translateY(0); }\n      .zad-offline-banner.offline { background: #b3261e; }\n      .zad-offline-banner.online { background: var(--green-mid,#1a5d47); }\n\n      .zad-disabled-offline { opacity: .45; position: relative; }\n      .zad-disabled-offline::after {\n        content: '📡'; position: absolute; top: 4px; left: 4px; font-size: 11px;\n      }\n\n      .zad-feature-block {\n        position: fixed; inset: 0; z-index: 9980; background: var(--bg,#f5f4f0);\n        display: flex; flex-direction: column; align-items: center; justify-content: center;\n        gap: 14px; padding: 32px; text-align: center;\n      }\n      .zfb-icon { font-size: 56px; }\n      .zfb-title { font-size: 20px; font-weight: 900; color: var(--ink,#222); }\n      .zfb-msg { font-size: 14px; color: var(--muted,#888); max-width: 320px; line-height: 1.7; }\n      .zfb-btn { margin-top: 12px; padding: 12px 28px; border-radius: 12px; border: none;\n        background: var(--green-deep,#0e3b2e); color: #fff; font-family: inherit;\n        font-size: 15px; font-weight: 700; cursor: pointer; min-height: 44px; }\n\n      @media (prefers-reduced-motion: reduce) {\n        .zad-offline-banner { transition: none !important; }\n      }\n    `;document.head.appendChild(s)}function handleOnline(){isOnline=true;showBanner(true);blockOnlineFeatures(false);document.getElementById("zad-feature-block")?.remove()}function handleOffline(){isOnline=false;showBanner(false);blockOnlineFeatures(true)}function init(){injectCSS();window.addEventListener("online",handleOnline);window.addEventListener("offline",handleOffline);if(!navigator.onLine){setTimeout(handleOffline,500)}}return{init:init,isOnline:()=>isOnline}})();window.ZadOffline=ZadOffline;document.addEventListener("DOMContentLoaded",()=>ZadOffline.init());